import { z } from 'zod';
import * as Emittery from 'emittery';
import Emittery__default from 'emittery';

interface DevDcUpdatedCtx {
    overrideId: string;
}
interface ExtensionRuntimeErrorCtx {
    componentStack?: string;
    error: Error;
    location: ProjectErrorLocation;
}
interface ProjectErrorLocation {
    file: string;
    line?: number;
    column?: number;
}
interface ProjectError {
    raw?: string;
    message?: string;
    location?: ProjectErrorLocation;
    stack?: string;
}
type CliErrorCtx = {
    type: 'cli-system';
    error: Error;
} | {
    type: 'cli-user';
    error: Error;
} | {
    type: 'project';
    errors: ProjectError[];
};
interface EventsMap {
    'cli-error': CliErrorCtx;
    'dc-updated': DevDcUpdatedCtx;
    'runtime-error': ExtensionRuntimeErrorCtx;
}

declare const PLATFORM_LINK_TYPES: readonly ["site", "dashboard", "editor"];
type PlatformLinkType = (typeof PLATFORM_LINK_TYPES)[number];
/** Commands that display platform links or write them to `.wix/topology.json`. */
type PlatformLinkCommand = 'dev' | 'preview' | 'release';
declare const platformLinkItemSchema: z.ZodObject<{
    platform: z.ZodEnum<["site", "dashboard", "editor"]>;
    label: z.ZodString;
    url: z.ZodString;
}, "strip", z.ZodTypeAny, {
    url: string;
    platform: "site" | "dashboard" | "editor";
    label: string;
}, {
    url: string;
    platform: "site" | "dashboard" | "editor";
    label: string;
}>;
type PlatformLinkItem = z.infer<typeof platformLinkItemSchema>;
interface PlatformLinkCtx {
    /** The command that is resolving the links. */
    cmd: PlatformLinkCommand;
    overrideId: string;
    appId: string;
    siteId?: string;
    /**
     * Links planned for rendering, in render order.
     * Reflects changes made by earlier plugins.
     */
    links: readonly PlatformLinkItem[];
}
/**
 * Returns the platform links (site, dashboard, editor) displayed by the Wix
 * CLI in the terminal and written to `.wix/topology.json`.
 *
 * - Return `ctx.links` as is to keep the current links.
 * - Change `label` / `url` of an item to override it.
 * - Omit an item to hide the link. Later plugins will not see it.
 * - Order of the returned list is the render order.
 *
 * Each `platform` may appear at most once. Only known platforms are accepted.
 * The CLI may still hide a returned link based on its own conditions, and
 * only known platforms are written to `.wix/topology.json`.
 *
 * Expected to be a pure and synchronous function. The CLI may call it any
 * number of times per command.
 */
type PlatformLinksHandler = (ctx: PlatformLinkCtx) => PlatformLinkItem[];

interface PluginsInterface {
    hooksEmitter: Emittery__default<HookPayloadsMap>;
    eventsEmitter: Emittery__default<EventsMap>;
    resolvePlatformLinks: (ctx: PlatformLinkCtx) => PlatformLinkItem[];
    onPluginError?: (error: unknown, context: {
        pluginName: string;
        handlerName: string;
    }) => void;
}

declare class UserEventWrapper {
    #private;
    constructor(pluginsInterface: PluginsInterface, pluginName: string);
    on<K extends keyof EventsMap>(key: K, callback: (data: EventsMap[K]) => void | Promise<void>): Emittery.UnsubscribeFunction;
}

type CliCommand = 'dev' | 'build' | 'preview';
interface HookPayloadsMap {
    'cli:setup': {
        cmd: CliCommand;
    };
}
interface UserHooksMap extends HookPayloadsMap {
    'cli:setup': {
        cmd: CliCommand;
        emitter: UserEventWrapper;
    };
}
type UserHooksHandlers = {
    [K in keyof UserHooksMap]?: (data: UserHooksMap[K]) => void | Promise<void>;
};

type WixAstroSiteOutputDirectory = {
    client: string;
    server?: string;
} | {
    client?: string;
    server: string;
};
interface WixAstroSiteConfig {
    $schema?: string;
    projectType: 'Site';
    appId: string;
    httpExperiments?: Record<string, boolean | string>;
    siteId: string;
    site?: {
        outputDirectory: string | WixAstroSiteOutputDirectory;
    };
}
interface WixAstroAppConfig {
    $schema?: string;
    projectType: 'App';
    appId: string;
    projectId?: string;
    codeIdentifier?: string;
    namespace?: string;
    httpExperiments?: Record<string, boolean | string>;
}
type WixAstroConfig = WixAstroSiteConfig | WixAstroAppConfig;
interface WixCliPluginShape {
    name: string;
    hooks?: Record<string, unknown>;
    platformLinks?: unknown;
}
interface WixCliPlugin extends WixCliPluginShape {
    hooks?: UserHooksHandlers;
    platformLinks?: PlatformLinksHandler;
}
interface DefineWixConfigOptions {
    config: WixAstroConfig;
    plugins?: WixCliPlugin[];
}

declare const defineWixConfig: (options: DefineWixConfigOptions) => DefineWixConfigOptions;

export { type CliErrorCtx, type PlatformLinkCommand, type PlatformLinkCtx, type PlatformLinkItem, type PlatformLinkType, type WixAstroConfig, type WixCliPlugin, defineWixConfig };
